import * as React from "react"
import { Link, graphql } from "gatsby"

import Bio from "../components/bio"
import Layout from "../components/layout"
import Seo from "../components/seo"
import { useLanguage } from "../components/language"
import { localizePost } from "../components/localize-post"

const BlogPostTemplate = ({
  data: {
    previous: sourcePrevious,
    next: sourceNext,
    site,
    allPosts,
    markdownRemark: sourcePost,
  },
  location,
}) => {
  const { locale, t } = useLanguage()
  const post = localizePost(sourcePost, locale)
  const previous = localizePost(sourcePrevious, locale)
  const next = localizePost(sourceNext, locale)
  const siteTitle = site.siteMetadata?.title || `Title`
  const articleCategory = post.fileAbsolutePath.includes("/content/news/")
    ? "news"
    : "blog"
  const articlePosts = allPosts.nodes.filter(item =>
    item.fileAbsolutePath.includes(`/content/${articleCategory}/`)
  )

  return (
    <Layout
      location={location}
      title={siteTitle}
      showBottomNavigation
      articleCategory={articleCategory}
      articlePosts={articlePosts}
    >
      <article
        className="blog-post"
        itemScope
        itemType="http://schema.org/Article"
      >
        <header>
          <h1 itemProp="headline">{post.frontmatter.title}</h1>
          <p>{post.frontmatter.date}</p>
        </header>
        <section
          className="article-body"
          dangerouslySetInnerHTML={{ __html: post.html }}
          itemProp="articleBody"
          style={{ fontSize: `0.9rem` }}
        />
      </article>
      <div className="article-end">
        <Bio />
        <nav
          className="blog-post-nav"
          aria-label={t("前後の記事", "Article navigation")}
        >
          <ul>
            {next && (
              <li className="li-post-nav">
                <Link
                  className="post-nav-button"
                  to={next.fields.slug}
                  rel="next"
                >
                  <span className="post-nav-label">
                    ← {t("ひとつ新しい記事", "Newer article")}
                  </span>
                  <span>{next.frontmatter.title}</span>
                </Link>
              </li>
            )}
            {previous && (
              <li className="li-post-nav li-post-nav-older">
                <Link
                  className="post-nav-button"
                  to={previous.fields.slug}
                  rel="prev"
                >
                  <span className="post-nav-label">
                    {t("ひとつ古い記事", "Older article")} →
                  </span>
                  <span>{previous.frontmatter.title}</span>
                </Link>
              </li>
            )}
          </ul>
        </nav>
      </div>
    </Layout>
  )
}

export const Head = ({ data: { markdownRemark: sourcePost } }) => {
  const { locale } = useLanguage()
  const post = localizePost(sourcePost, locale)
  return (
    <Seo
      title={post.frontmatter.title}
      description={post.frontmatter.description || post.excerpt}
    />
  )
}

export default BlogPostTemplate

export const pageQuery = graphql`
  query BlogPostBySlug(
    $id: String!
    $previousPostId: String
    $nextPostId: String
  ) {
    site {
      siteMetadata {
        title
      }
    }
    allPosts: allMarkdownRemark(
      filter: { fields: { locale: { eq: "ja" } } }
      sort: { frontmatter: { date: DESC } }
    ) {
      nodes {
        english {
          excerpt(pruneLength: 55)
          frontmatter {
            title
            description
          }
        }
        id
        fileAbsolutePath
        excerpt(pruneLength: 55)
        fields {
          slug
        }
        frontmatter {
          title
          description
          date(formatString: "YYYY.MM.DD")
          rawDate: date
        }
      }
    }
    markdownRemark(id: { eq: $id }) {
      english {
        html
        excerpt(pruneLength: 160)
        frontmatter {
          title
          description
        }
      }
      fields {
        slug
      }
      fileAbsolutePath
      id
      excerpt(pruneLength: 160)
      html
      frontmatter {
        title
        date(formatString: "MMMM DD, YYYY")
        description
      }
    }
    previous: markdownRemark(id: { eq: $previousPostId }) {
      english {
        frontmatter {
          title
        }
      }
      fields {
        slug
      }
      frontmatter {
        title
      }
    }
    next: markdownRemark(id: { eq: $nextPostId }) {
      english {
        frontmatter {
          title
        }
      }
      fields {
        slug
      }
      frontmatter {
        title
      }
    }
  }
`
